      "status": {"code": "ACTIVE"},
      "commitments": [
        {
          "id": "commitment-tariff-policy-001",
          "status": {"descriptor": {"code": "ACTIVE"}},
          "resources": [{"id": "ds-tariff-policy-mum-res-2024-25", "descriptor": {"name": "Mumbai Residential Telescopic Tariff 2024-25"}, "quantity": {"unitText": "policy", "unitCode": "EA", "value": "1"}}],
          "offer": {"id": "offer-tariff-policy-inline", "descriptor": {"name": "Inline Tariff Policy Delivery - Mumbai Residential 2024-25"}, "resourceIds": ["ds-tariff-policy-mum-res-2024-25"]},
          "commitmentAttributes": {
            "@context": "https://schema.nfh.global/DatasetItem/v1.1/context.jsonld",
            "@type": "DatasetItem",
            "schema:identifier": "ds-tariff-policy-mum-res-2024-25",
            "schema:name": "Mumbai Residential Telescopic Tariff 2024-25",
            "schema:temporalCoverage": "2024-04-01/2025-03-31",
            "dataset:accessMethod": "INLINE"
          }
        }
      ],
      "consideration": [
        {
          "id": "consideration-tariff-public-good",
          "status": {"code": "ACTIVE"},
          "considerationAttributes": {
            "@context": "https://schema.nfh.global/PriceSpecification/v2.1/context.jsonld",
            "@type": "PriceSpecification",
            "currency": "INR",
            "value": 0,
            "description": "Tariff orders are public regulatory artefacts — distributed at zero cost under MERC public-disclosure norms"
          }
        }
      ],
      "participants": [{"id": "merc-regulator-001", "descriptor": {"name": "Maharashtra Electricity Regulatory Commission"}}, {"id": "merashehar-discom-001", "descriptor": {"name": "MeraShehar - Distribution Company"}}],
      "performance": [],
      "settlements": [
        {
          "id": "settlement-tariff-no-charge",
          "considerationId": "consideration-tariff-public-good",
          "status": "COMPLETE",
          "settlementAttributes": {
            "@context": "https://schema.nfh.global/Payment/v2.0/context.jsonld",
            "@type": "Payment",
            "beckn:paymentStatus": "COMPLETED",
            "beckn:amount": {"currency": "INR", "value": 0}
          }
        }
      ]
    }
  }
}

